public Yaf_Request_AbstractnullYaf_Request_Abstract::setControllerName stringcontroller boolformat_nametrue
Define o nome do controlador para solicitação. Isso geralmente é usado pelo roteador personalizado para definir o nome do controlador de resultado da rota.

  &reftitle.examples;

   Exemplo de Yaf_Request_Abstract::setControllerName


<?php
class RestRouter extends Yaf_Route_Interface
{
    public function route(Yaf_Request_Abstract $request)
    {
        if (0 === strpos($request->getRequestUri(), "/api")) {
            // Os nomes são formatados no estilo camel por padrão,
            // so "order_item" becomes "Order_Item"
            $request->setControllerName("order_item")
                    ->setActionName("list");
            return true;
        }

        return false;
    }

    public function assemble(array $info, array $query = null) {}
}
?>
